From 3aa5d7928abcbd021703f519c340b6f8c9689706 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:31:06 +0100
Subject: [PATCH] containments/desktop: place new and dropped items in the cell
 under the pointer

Items without a drag offset, like files made with Create New or dropped
from another app, were still shifted by half a cell and by the icon
offset of the last drag, landing one cell to the right. Use the pointer.

BUG: 518069
---
 .../desktop/package/contents/ui/FolderView.qml       | 12 +++++++++---
 1 file changed, 9 insertions(+), 3 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..bd35631fb6 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -1288,9 +1288,15 @@ FocusScope {
                         continue;
                     }

-                    // The +(gridView.cellWidth / 2) is kept here to make it easier to drag items between cells.
-                    itemX = dropPos.x + offset.x + (gridView.cellWidth / 2);
-                    itemY = dropPos.y + offset.y + gridView.verticalDropHitscanOffset;
+                    if (offset.x === 0 && offset.y === 0) {
+                        // Not dragged from this view (new or dropped item), so use the pointer position.
+                        itemX = dropPos.x;
+                        itemY = dropPos.y;
+                    } else {
+                        // The +(gridView.cellWidth / 2) is kept here to make it easier to drag items between cells.
+                        itemX = dropPos.x + offset.x + (gridView.cellWidth / 2);
+                        itemY = dropPos.y + offset.y + gridView.verticalDropHitscanOffset;
+                    }


                     if (gridView.effectiveLayoutDirection === Qt.RightToLeft) {
-- 
